135	pub fn parse_calendar(
136	    input: &str,
137	    limits: IcsParserLimits,
138	) -> Result<NormalizedCalendar, IcsParseError> {
139	    if limits.max_components == 0
140	        || limits.max_events == 0
141	        || limits.max_component_bytes == 0
142	        || limits.max_text_bytes == 0
143	        || limits.max_recurrence_values == 0
144	    {
145	        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
146	    }
147	    let lines = unfold(input)?;
148	    let mut stack = Vec::new();
149	    let mut components = 0_usize;
150	    let mut current: Option<Vec<Property>> = None;
151	    let mut current_alarm: Option<Vec<Property>> = None;
152	    let mut alarms: Vec<Vec<Property>> = Vec::new();
153	    let mut scheduling: Vec<String> = Vec::new();
154	    let mut has_method = false;
155	    let mut events = Vec::new();
156	    let mut keys = HashSet::new();
157	    for line in lines {
158	        let property = property(&line)?;
159	        match (property.name.as_str(), property.value.as_str()) {
160	            ("BEGIN", name) => {
161	                components += 1;
162	                if components > limits.max_components {
163	                    return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
164	                }
165	                if name != "VCALENDAR"
166	                    && name != "VEVENT"
167	                    && name != "VTIMEZONE"
168	                    && name != "STANDARD"
169	                    && name != "DAYLIGHT"
170	                    && name != "VALARM"
171	                {
172	                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
173	                }
174	                if name == "VCALENDAR" && !stack.is_empty() {
175	                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
176	                }
177	                if name == "VEVENT" && stack.last().map(String::as_str) != Some("VCALENDAR") {
178	                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
179	                }
180	                if name == "VALARM" && stack.last().map(String::as_str) != Some("VEVENT") {
181	                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
182	                }
183	                if name == "VEVENT" {
184	                    current = Some(Vec::new());
185	                    alarms.clear();
186	                    scheduling.clear();
187	                }
188	                if name == "VALARM" {
189	                    current_alarm = Some(Vec::new());
190	                }
191	                stack.push(name.to_owned());
192	            }
193	            ("END", name) => {
194	                if stack.pop().as_deref() != Some(name) {
195	                    return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
196	                }
197	                if name == "VALARM"
198	                    && let Some(alarm) = current_alarm.take()
199	                {
200	                    alarms.push(alarm);
201	                }
202	                if name == "VEVENT" {
203	                    let event = normalize_event(
204	                        current
205	                            .take()
206	                            .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?,
207	                        &alarms,
208	                        &scheduling,
209	                        limits,
210	                    )?;
211	                    let key = (event.uid.clone(), event.recurrence_id.clone());
212	                    if !keys.insert(key) {
213	                        return Err(IcsParseError::new(IcsParseErrorCode::DuplicateEvent));
214	                    }
215	                    events.push(event);
216	                    if events.len() > limits.max_events {
217	                        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
218	                    }
219	                }
220	            }
221	            _ => match stack.last().map(String::as_str) {
222	                Some("VEVENT") => {
223	                    if (property.name == "ATTENDEE" || property.name == "ORGANIZER")
224	                        && !scheduling.contains(&property.name)
225	                    {
226	                        scheduling.push(property.name.clone());
227	                    }
228	                    let target = current
229	                        .as_mut()
230	                        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
231	                    let bytes = target.iter().map(|p| p.raw_len).sum::<usize>() + property.raw_len;
232	                    if bytes > limits.max_component_bytes {
233	                        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
234	                    }
235	                    target.push(property);
236	                }
237	                Some("VALARM") => {
238	                    let target = current_alarm
239	                        .as_mut()
240	                        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
241	                    let bytes = target.iter().map(|p| p.raw_len).sum::<usize>() + property.raw_len;
242	                    if bytes > limits.max_component_bytes {
243	                        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
244	                    }
245	                    target.push(property);
246	                }
247	                Some("VCALENDAR") if property.name == "METHOD" => {
248	                    has_method = true;
249	                }
250	                _ => {}
251	            },
252	        }
253	    }
254	    if !stack.is_empty() || events.is_empty() {
255	        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
256	    }
257	    Ok(NormalizedCalendar { events, has_method })
258	}
