330	fn normalize_event(
331	    properties: Vec<Property>,
332	    alarms: &[Vec<Property>],
333	    scheduling: &[String],
334	    limits: IcsParserLimits,
335	) -> Result<NormalizedEvent, IcsParseError> {
336	    let x_properties = collect_x_properties(&properties, limits)?;
337	    let mut fields: HashMap<String, Vec<Property>> = HashMap::new();
338	    for p in properties {
339	        fields.entry(p.name.clone()).or_default().push(p);
340	    }
341	    for name in [
342	        "UID",
343	        "DTSTART",
344	        "DTEND",
345	        "DURATION",
346	        "SUMMARY",
347	        "DESCRIPTION",
348	        "LOCATION",
349	        "STATUS",
350	        "RRULE",
351	        "RECURRENCE-ID",
352	        "SEQUENCE",
353	        "DTSTAMP",
354	        "LAST-MODIFIED",
355	    ] {
356	        if fields.get(name).is_some_and(|values| values.len() > 1) {
357	            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
358	        }
359	    }
360	    let one = |name: &str| fields.get(name).and_then(|v| v.first());
361	    let uid = text(
362	        one("UID").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?,
363	        limits,
364	    )?;
365	    if uid.is_empty() {
366	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
367	    }
368	    let start =
369	        date_value(one("DTSTART").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?)?;
370	    let end = one("DTEND").map(date_value).transpose()?;
371	    let duration = one("DURATION")
372	        .map(|p| parse_duration(&p.value))
373	        .transpose()?;
374	    if end.is_some() == duration.is_some() {
375	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
376	    }
377	    let timezone = one("DTSTART").and_then(|p| p.params.get("TZID")).cloned();
378	    if let Some(end_property) = one("DTEND")
379	        && end_property.params.get("TZID").cloned() != timezone
380	    {
381	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
382	    }
383	    let timing = timing(start, end, duration, timezone)?;
384	    let recurrence_id = one("RECURRENCE-ID").map(date_value).transpose()?;
385	    if recurrence_id
386	        .as_ref()
387	        .is_some_and(|v| !same_kind(v, &timing))
388	    {
389	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
390	    }
391	    let mut exdates = Vec::new();
392	    for p in fields.get("EXDATE").into_iter().flatten() {
393	        for value in p.value.split(',') {
394	            let copied = Property {
395	                value: value.to_owned(),
396	                ..p.clone()
397	            };
398	            let value = date_value(&copied)?;
399	            if !same_kind(&value, &timing) {
400	                return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
401	            }
402	            exdates.push(value);
403	            if exdates.len() > limits.max_recurrence_values {
404	                return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
405	            }
406	        }
407	    }
408	    let rrule = one("RRULE").map(|p| p.value.clone());
409	    if let Some(rule) = &rrule {
410	        if rule.split(';').count() > limits.max_recurrence_values {
411	            return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
412	        }
413	        if RecurrenceRule::parse(rule).is_err() {
414	            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
415	        }
416	    }
417	    let status = one("STATUS").map(|p| p.value.clone());
418	    if status
419	        .as_deref()
420	        .is_some_and(|s| !matches!(s, "CONFIRMED" | "TENTATIVE" | "CANCELLED"))
421	    {
422	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
423	    }
424	    let transp = one("TRANSP").map(|p| p.value.to_ascii_uppercase());
425	    if transp
426	        .as_deref()
427	        .is_some_and(|t| !matches!(t, "OPAQUE" | "TRANSPARENT"))
428	    {
429	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
430	    }
431	    let categories = fields
432	        .get("CATEGORIES")
433	        .into_iter()
434	        .flatten()
435	        .map(|p| {
436	            // Split raw TEXT before unescaping so escaped commas stay in one value.
437	            let mut escaped = false;
438	            p.value
439	                .split(|character| {
440	                    if escaped {
441	                        escaped = false;
442	                        return false;
443	                    }
444	                    if character == '\\' {
445	                        escaped = true;
446	                        return false;
447	                    }
448	                    character == ','
449	                })
450	                .map(|value| {
451	                    let mut category = p.clone();
452	                    category.value = value.to_owned();
453	                    text(&category, limits)
454	                })
455	                .collect::<Result<Vec<_>, _>>()
456	        })
457	        .collect::<Result<Vec<_>, _>>()?
458	        .into_iter()
459	        .flatten()
460	        .filter(|value| !value.is_empty())
461	        .collect();
462	    // URI-valued properties do not use TEXT backslash escaping.
463	    let url = one("URL")
464	        .map(|p| {
465	            if p.value.len() > limits.max_text_bytes {
466	                return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
467	            }
468	            Ok(p.value.clone())
469	        })
470	        .transpose()?;
471	    let normalized_alarms = normalize_alarms(alarms, limits)?;
472	    Ok(NormalizedEvent {
473	        uid,
474	        timing,
475	        summary: one("SUMMARY")
476	            .map(|p| text(p, limits))
477	            .transpose()?
478	            .unwrap_or_default(),
479	        description: one("DESCRIPTION").map(|p| text(p, limits)).transpose()?,
480	        location: one("LOCATION").map(|p| text(p, limits)).transpose()?,
481	        status,
482	        rrule,
483	        exdates,
484	        recurrence_id,
485	        sequence: one("SEQUENCE")
486	            .map(|p| p.value.parse())
487	            .transpose()
488	            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?
489	            .unwrap_or(0),
490	        dtstamp: one("DTSTAMP").map(utc_datetime).transpose()?,
491	        last_modified: one("LAST-MODIFIED").map(utc_datetime).transpose()?,
492	        categories,
493	        url,
494	        transp,
495	        alarms: normalized_alarms,
496	        x_properties,
497	        scheduling: scheduling.to_vec(),
498	    })
499	}
