260	#[derive(Clone)]
261	struct Property {
262	    name: String,
263	    params: HashMap<String, String>,
264	    value: String,
265	    raw_len: usize,
266	}
267	fn unfold(input: &str) -> Result<Vec<String>, IcsParseError> {
268	    let mut lines: Vec<String> = Vec::new();
269	    for raw in input.lines() {
270	        let line = raw.strip_suffix('\r').unwrap_or(raw);
271	        if line.starts_with(' ') || line.starts_with('\t') {
272	            lines
273	                .last_mut()
274	                .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?
275	                .push_str(&line[1..]);
276	        } else if !line.is_empty() {
277	            lines.push(line.to_owned());
278	        }
279	    }
280	    if lines.is_empty() {
281	        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
282	    }
283	    Ok(lines)
284	}
285	fn property(line: &str) -> Result<Property, IcsParseError> {
286	    // Delimiters inside quoted parameter values are data (RFC 5545 §3.1).
287	    let mut quoted = false;
288	    let separator = line
289	        .char_indices()
290	        .find_map(|(index, character)| {
291	            if character == '"' {
292	                quoted = !quoted;
293	            }
294	            (character == ':' && !quoted).then_some(index)
295	        })
296	        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
297	    let (left, remainder) = line.split_at(separator);
298	    let value = &remainder[1..];
299	    quoted = false;
300	    let mut parts = left.split(|character| {
301	        if character == '"' {
302	            quoted = !quoted;
303	        }
304	        character == ';' && !quoted
305	    });
306	    let name = parts.next().unwrap().to_ascii_uppercase();
307	    if name.is_empty() || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
308	        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
309	    }
310	    let mut params = HashMap::new();
311	    for part in parts {
312	        let (key, value) = part
313	            .split_once('=')
314	            .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
315	        if params
316	            .insert(key.to_ascii_uppercase(), value.trim_matches('"').to_owned())
317	            .is_some()
318	        {
319	            return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
320	        }
321	    }
322	    Ok(Property {
323	        name,
324	        params,
325	        value: value.to_owned(),
326	        raw_len: line.len(),
327	    })
328	}
329	
330	fn normalize_event(
331	    properties: Vec<Property>,
332	    alarms: &[Vec<Property>],
333	    scheduling: &[String],
334	    limits: IcsParserLimits,
335	) -> Result<NormalizedEvent, IcsParseError> {
336	    let x_properties = collect_x_properties(&properties, limits)?;
337	    let mut fields: HashMap<String, Vec<Property>> = HashMap::new();
338	    for p in properties {
339	        fields.entry(p.name.clone()).or_default().push(p);
340	    }
341	    for name in [
342	        "UID",
343	        "DTSTART",
344	        "DTEND",
345	        "DURATION",
346	        "SUMMARY",
347	        "DESCRIPTION",
348	        "LOCATION",
349	        "STATUS",
350	        "RRULE",
351	        "RECURRENCE-ID",
352	        "SEQUENCE",
353	        "DTSTAMP",
354	        "LAST-MODIFIED",
355	    ] {
356	        if fields.get(name).is_some_and(|values| values.len() > 1) {
357	            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
358	        }
359	    }
360	    let one = |name: &str| fields.get(name).and_then(|v| v.first());
361	    let uid = text(
362	        one("UID").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?,
363	        limits,
364	    )?;
365	    if uid.is_empty() {
366	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
367	    }
368	    let start =
369	        date_value(one("DTSTART").ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?)?;
370	    let end = one("DTEND").map(date_value).transpose()?;
371	    let duration = one("DURATION")
372	        .map(|p| parse_duration(&p.value))
373	        .transpose()?;
374	    if end.is_some() == duration.is_some() {
375	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
376	    }
377	    let timezone = one("DTSTART").and_then(|p| p.params.get("TZID")).cloned();
378	    if let Some(end_property) = one("DTEND")
379	        && end_property.params.get("TZID").cloned() != timezone
380	    {
381	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
382	    }
383	    let timing = timing(start, end, duration, timezone)?;
384	    let recurrence_id = one("RECURRENCE-ID").map(date_value).transpose()?;
385	    if recurrence_id
386	        .as_ref()
387	        .is_some_and(|v| !same_kind(v, &timing))
388	    {
389	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
390	    }
391	    let mut exdates = Vec::new();
392	    for p in fields.get("EXDATE").into_iter().flatten() {
393	        for value in p.value.split(',') {
394	            let copied = Property {
395	                value: value.to_owned(),
396	                ..p.clone()
397	            };
398	            let value = date_value(&copied)?;
399	            if !same_kind(&value, &timing) {
400	                return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
401	            }
402	            exdates.push(value);
403	            if exdates.len() > limits.max_recurrence_values {
404	                return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
405	            }
406	        }
407	    }
408	    let rrule = one("RRULE").map(|p| p.value.clone());
409	    if let Some(rule) = &rrule {
410	        if rule.split(';').count() > limits.max_recurrence_values {
411	            return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
412	        }
413	        if RecurrenceRule::parse(rule).is_err() {
414	            return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
415	        }
416	    }
417	    let status = one("STATUS").map(|p| p.value.clone());
418	    if status
419	        .as_deref()
420	        .is_some_and(|s| !matches!(s, "CONFIRMED" | "TENTATIVE" | "CANCELLED"))
421	    {
422	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
423	    }
424	    let transp = one("TRANSP").map(|p| p.value.to_ascii_uppercase());
425	    if transp
426	        .as_deref()
427	        .is_some_and(|t| !matches!(t, "OPAQUE" | "TRANSPARENT"))
428	    {
429	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
430	    }
431	    let categories = fields
432	        .get("CATEGORIES")
433	        .into_iter()
434	        .flatten()
435	        .map(|p| {
436	            // Split raw TEXT before unescaping so escaped commas stay in one value.
437	            let mut escaped = false;
438	            p.value
439	                .split(|character| {
440	                    if escaped {
441	                        escaped = false;
442	                        return false;
443	                    }
444	                    if character == '\\' {
445	                        escaped = true;
446	                        return false;
447	                    }
448	                    character == ','
449	                })
450	                .map(|value| {
451	                    let mut category = p.clone();
452	                    category.value = value.to_owned();
453	                    text(&category, limits)
454	                })
455	                .collect::<Result<Vec<_>, _>>()
456	        })
457	        .collect::<Result<Vec<_>, _>>()?
458	        .into_iter()
459	        .flatten()
460	        .filter(|value| !value.is_empty())
461	        .collect();
462	    // URI-valued properties do not use TEXT backslash escaping.
463	    let url = one("URL")
464	        .map(|p| {
465	            if p.value.len() > limits.max_text_bytes {
466	                return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
467	            }
468	            Ok(p.value.clone())
469	        })
470	        .transpose()?;
471	    let normalized_alarms = normalize_alarms(alarms, limits)?;
472	    Ok(NormalizedEvent {
473	        uid,
474	        timing,
475	        summary: one("SUMMARY")
476	            .map(|p| text(p, limits))
477	            .transpose()?
478	            .unwrap_or_default(),
479	        description: one("DESCRIPTION").map(|p| text(p, limits)).transpose()?,
480	        location: one("LOCATION").map(|p| text(p, limits)).transpose()?,
481	        status,
482	        rrule,
483	        exdates,
484	        recurrence_id,
485	        sequence: one("SEQUENCE")
486	            .map(|p| p.value.parse())
487	            .transpose()
488	            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?
489	            .unwrap_or(0),
490	        dtstamp: one("DTSTAMP").map(utc_datetime).transpose()?,
491	        last_modified: one("LAST-MODIFIED").map(utc_datetime).transpose()?,
492	        categories,
493	        url,
494	        transp,
495	        alarms: normalized_alarms,
496	        x_properties,
497	        scheduling: scheduling.to_vec(),
498	    })
499	}
500	
501	/// The bounded set of X-properties that are preserved. Any other X-property is
502	/// ignored by the parser (it is neither preserved nor rejected here); the DAV
503	/// layer enforces the write-time policy.
504	const ALLOWED_X_PROPERTIES: &[&str] = &[
505	    "X-APPLE-CEVENT-CATEGORY",
506	    "X-APPLE-STRUCTURED-LOCATION",
507	    "X-APPLE-FALLBACK-ALARM-UID",
508	];
509	
510	/// Collect the allowlisted X-properties from a VEVENT's properties, in
511	/// document order. Non-allowlisted X-properties are ignored.
512	fn collect_x_properties(
513	    properties: &[Property],
514	    limits: IcsParserLimits,
515	) -> Result<Vec<NormalizedXProperty>, IcsParseError> {
516	    let mut out = Vec::new();
517	    for property in properties {
518	        if !property.name.starts_with("X-") {
519	            continue;
520	        }
521	        if !ALLOWED_X_PROPERTIES.contains(&property.name.as_str()) {
522	            continue;
523	        }
524	        let value = text(property, limits)?;
525	        out.push(NormalizedXProperty {
526	            name: property.name.clone(),
527	            value,
528	        });
529	    }
530	    Ok(out)
531	}
532	
533	/// Normalize the VALARM subcomponents of a VEVENT into `NormalizedAlarm`s.
534	///
535	/// Only `DISPLAY` and `AUDIO` alarms with a `TRIGGER` are preserved. Alarms
536	/// with other actions (e.g. `EMAIL`) or without a trigger are dropped, so the
537	/// preserved set is bounded and deterministic.
538	fn normalize_alarms(
539	    alarms: &[Vec<Property>],
540	    limits: IcsParserLimits,
541	) -> Result<Vec<NormalizedAlarm>, IcsParseError> {
542	    let mut out = Vec::with_capacity(alarms.len());
543	    for alarm in alarms {
544	        let mut action = None;
545	        let mut trigger = None;
546	        let mut description = None;
547	        for p in alarm {
548	            match p.name.as_str() {
549	                "ACTION" => action = Some(p.value.to_ascii_uppercase()),
550	                "TRIGGER" => trigger = Some(p.value.clone()),
551	                "DESCRIPTION" => description = Some(text(p, limits)?),
552	                _ => {}
553	            }
554	        }
555	        let Some(action) = action else {
556	            continue;
557	        };
558	        if !matches!(action.as_str(), "DISPLAY" | "AUDIO") {
559	            continue;
560	        }
561	        let Some(trigger) = trigger else {
562	            continue;
563	        };
564	        out.push(NormalizedAlarm {
565	            action,
566	            trigger,
567	            description,
568	        });
