723	// Preserve the supplied VTIMEZONE as metadata. Event interpretation continues
724	// to use the existing IANA timezone implementation.
725	pub(crate) fn valid_calendar_timezone(text: &str) -> Option<String> {
726	    let lines = unfold(text)
727	        .ok()?
728	        .iter()
729	        .map(|line| property(line))
730	        .collect::<Result<Vec<_>, _>>()
731	        .ok()?;
732	    let mut stack: Vec<&str> = Vec::new();
733	    let mut calendars = 0;
734	    let mut zones = 0;
735	    let mut observances = 0;
736	    let mut tzid = None;
737	    let mut required = [false; 3];
738	    let mut version = false;
739	    let mut prodid = false;
740	    for line in &lines {
741	        let name = line.name.as_str();
742	        let value = line.value.as_str();
743	        match (name, value) {
744	            ("BEGIN", "VCALENDAR") if stack.is_empty() && calendars == 0 => {
745	                calendars += 1;
746	                stack.push(value);
747	            }
748	            ("BEGIN", "VTIMEZONE") if stack == ["VCALENDAR"] => {
749	                zones += 1;
750	                stack.push(value);
751	            }
752	            ("BEGIN", "STANDARD" | "DAYLIGHT") if stack == ["VCALENDAR", "VTIMEZONE"] => {
753	                observances += 1;
754	                required = [false; 3];
755	                stack.push(value);
756	            }
757	            ("BEGIN", _) => return None,
758	            ("END", _) => {
759	                if matches!(stack.last(), Some(&"STANDARD" | &"DAYLIGHT"))
760	                    && !required.iter().all(|v| *v)
761	                {
762	                    return None;
763	                }
764	                if stack.pop()? != value {
765	                    return None;
766	                }
767	            }
768	            ("VERSION", "2.0") if stack == ["VCALENDAR"] && !version => version = true,
769	            ("PRODID", _) if stack == ["VCALENDAR"] && !prodid => prodid = !value.is_empty(),
770	            ("VERSION" | "PRODID" | "METHOD", _) if stack == ["VCALENDAR"] => return None,
771	            ("TZID", _) if stack == ["VCALENDAR", "VTIMEZONE"] => {
772	                if tzid.is_some() || value.is_empty() {
773	                    return None;
774	                }
775	                tzid = Some(value.to_owned());
776	            }
777	            ("DTSTART", _) if stack.len() == 3 => {
778	                NaiveDateTime::parse_from_str(value, "%Y%m%dT%H%M%S").ok()?;
779	                if required[0] {
780	                    return None;
781	                }
782	                required[0] = true;
783	            }
784	            ("TZOFFSETFROM" | "TZOFFSETTO", _) if stack.len() == 3 => {
785	                let bytes = value.as_bytes();
786	                if !matches!(bytes.len(), 5 | 7)
787	                    || !matches!(bytes[0], b'+' | b'-')
788	                    || !bytes[1..].iter().all(u8::is_ascii_digit)
789	                    || value[1..3].parse::<u8>().ok()? > 23
790	                    || value[3..5].parse::<u8>().ok()? > 59
791	                    || (bytes.len() == 7 && value[5..7].parse::<u8>().ok()? > 59)
792	                {
793	                    return None;
794	                }
795	                let index = if name == "TZOFFSETFROM" { 1 } else { 2 };
796	                if required[index] {
797	                    return None;
798	                }
799	                required[index] = true;
800	            }
801	            _ if stack.is_empty() => return None,
802	            _ => {}
803	        }
804	    }
805	    if zones == 1 && observances > 0 && stack.is_empty() && version && prodid {
806	        tzid
807	    } else {
808	        None
809	    }
810	}

