229	async fn ics_import_service_converts_standalone_recurrence_and_reimports() {
230	    let (_dir, pool, owner, calendar_id) = setup().await;
231	    let service = IcsImportService::new(EventService::new_at(pool.clone(), NOW));
232	    let input = b"BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nUID:timed\r\nDTSTART;TZID=Europe/Budapest:20250616T100000\r\nDTEND;TZID=Europe/Budapest:20250616T110000\r\nSUMMARY:Timed\r\nDESCRIPTION:Description\r\nLOCATION:Room\r\nSTATUS:TENTATIVE\r\nEND:VEVENT\r\nBEGIN:VEVENT\r\nUID:day\r\nDTSTART;VALUE=DATE:20250617\r\nDTEND;VALUE=DATE:20250618\r\nSUMMARY:All day\r\nEND:VEVENT\r\nBEGIN:VEVENT\r\nUID:series\r\nDTSTART:20250619T090000Z\r\nDTEND:20250619T100000Z\r\nSUMMARY:Series\r\nRRULE:FREQ=DAILY;COUNT=3\r\nEXDATE:20250620T090000Z\r\nEND:VEVENT\r\nBEGIN:VEVENT\r\nUID:series\r\nRECURRENCE-ID:20250621T090000Z\r\nDTSTART:20250621T120000Z\r\nDTEND:20250621T130000Z\r\nSUMMARY:Moved\r\nSTATUS:CANCELLED\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";
233	
234	    let summary = service
235	        .import(owner, false, calendar_id, input)
236	        .await
237	        .unwrap();
238	    assert_eq!(summary.imported_events, 3);
239	    assert_eq!(summary.imported_exceptions, 2);
240	    let timed: (String, Option<String>, String, String, i64, i64) = sqlx::query_as(
241	        "SELECT title, description, status, event_timezone, timed_start_utc, timed_end_utc
242	         FROM events WHERE title = 'Timed'",
243	    )
244	    .fetch_one(&pool)
245	    .await
246	    .unwrap();
247	    assert_eq!(timed.0, "Timed");
248	    assert_eq!(timed.1.as_deref(), Some("Description"));
249	    assert_eq!(timed.2, "tentative");
250	    assert_eq!(timed.3, "Europe/Budapest");
251	    assert!(timed.4 < timed.5);
252	    let all_day: (String, String) = sqlx::query_as(
253	        "SELECT all_day_start_date, all_day_end_date FROM events WHERE title = 'All day'",
254	    )
255	    .fetch_one(&pool)
256	    .await
257	    .unwrap();
258	    assert_eq!(all_day, ("2025-06-17".into(), "2025-06-18".into()));
259	    let exceptions: Vec<ExceptionStatusRow> = sqlx::query_as(
260	        "SELECT recurrence_id, is_deleted, title, status
261	         FROM event_recurrence_exceptions ORDER BY recurrence_id",
262	    )
263	    .fetch_all(&pool)
264	    .await
265	    .unwrap();
266	    assert_eq!(exceptions.len(), 2);
267	    assert!(exceptions[0].1);
268	    assert!(!exceptions[1].1);
269	    assert_eq!(exceptions[1].2.as_deref(), Some("Moved"));
270	    assert_eq!(exceptions[1].3.as_deref(), Some("cancelled"));
271	
272	    let again = service
273	        .import(owner, false, calendar_id, input)
274	        .await
275	        .unwrap();
276	    assert_eq!(again.imported_events, 3);
277	    assert_eq!(
278	        sqlx::query_scalar::<_, i64>("SELECT COUNT(*) FROM events")
279	            .fetch_one(&pool)
280	            .await
281	            .unwrap(),
282	        6
283	    );
284	}
