609	    fn router(&self) -> axum::Router {
610	        apply_shared_middleware(
611	            build_router_with_auth_flows_sessions_admin_and_calendars(
612	                Readiness::new(),
613	                InvitationConsumer::new_at(self.pool.clone(), self.key.clone(), NOW),
614	                LoginService::new_at(
615	                    self.pool.clone(),
616	                    self.key.clone(),
617	                    300,
618	                    300,
619	                    "/login",
620	                    Arc::new(DevelopmentEmailSender::new()),
621	                    Arc::new(AllowAllLoginRateLimiter),
622	                    NOW,
623	                    false,
624	                ),
625	                SessionManager::new_at(
626	                    self.pool.clone(),
627	                    self.key.clone(),
628	                    SessionSecurityConfig::new(300, 60, ORIGIN).unwrap(),
629	                    NOW,
630	                ),
631	                AdminService::new_at(self.pool.clone(), self.key.clone(), 300, NOW),
632	                CalendarService::new_at(self.pool.clone(), NOW),
633	                EventService::new_at(self.pool.clone(), NOW),
634	                None,
635	                None,
636	                None,
637	            ),
638	            AccessLogConfig::new(tracing::level_filters::LevelFilter::DEBUG),
639	            ResponseSecurityConfig::local_http(),
640	        )
641	    }
642	
643	    async fn request(
644	        &self,
645	        user_id: i64,
646	        path: &str,
647	        content_type: &str,
648	        body: Vec<u8>,
649	    ) -> axum::response::Response {
650	        let token = self.key.generate_token();
651	        let hash = self.key.hash_token(TokenDomain::Session, &token);
652	        sqlx::query(
653	            "INSERT INTO sessions (user_id, session_hash, expires_at, revoked_at, created_at, last_seen_at)
654	             VALUES (?, ?, ?, NULL, ?, ?)",
655	        )
656	        .bind(user_id)
657	        .bind(hash.as_bytes().as_slice())
658	        .bind(NOW + 1_000)
659	        .bind(NOW - 10)
660	        .bind(NOW - 10)
661	        .execute(&self.pool)
662	        .await
663	        .unwrap();
664	        let csrf = self.key.generate_csrf_token(&token);
665	        self.router()
666	            .oneshot(
667	                Request::builder()
668	                    .method(Method::POST)
669	                    .uri(path)
670	                    .header(
671	                        COOKIE,
672	                        format!("__Host-commoncal_session={}", token.expose()),
673	                    )
674	                    .header("content-type", content_type)
675	                    .header("origin", ORIGIN)
676	                    .header("sec-fetch-site", "same-origin")
677	                    .header("x-csrf-token", csrf.expose())
678	                    .body(Body::from(body))
679	                    .unwrap(),
680	            )
681	            .await
682	            .unwrap()
683	    }
684	}
